\bibitem{Leibo2025} Leibo, J. Z., et al. (2025). \textit{Theory of Mind and Social Reasoning in Artificial Intelligence}. Nature Machine Intelligence.
\bibitem{Park2024} Park, J. S., et al. (2024). \textit{Do AI Models Have Personality? Large Language Models Exhibit Stable Personality Profiles}. ACL 2024.
\end{thebibliography}

\end{document}

